contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint256 minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;
        bool reverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted && c.MinSum() == minSumBefore && address(c).balance == balanceBefore);
    }

    receive() external payable {}
}

