// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 minSum) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 minSumBefore;
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        uint256 balanceBefore = address(c).balance;
        bool reverted;
        try c.Initialized() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && c.MinSum() == minSumBefore && address(c).balance == balanceBefore);
    }

    function testFuzz_run(uint256 minSum) public {
        _run(minSum);
    }

    receive() external payable {}
}
